// TestForm — Step chooses the first matching row of Platform/03-worker/forms/slot-capture.tsv with its arguments, or waits.
func TestForm(t *testing.T) {
	for k, c := range formCases {
		m, ok, err := Step(c.state, c.in)
		if c.overflow {
			if !errors.Is(err, ErrOverflow) {
				t.Errorf("case %d (%s %+v): err %v, want overflow", k, c.state, c.in, err)
			}
			continue
		}
		if err != nil || ok != c.ok {
			t.Errorf("case %d (%s %+v): ok %v err %v, want ok %v (row %d)", k, c.state, c.in, ok, err, c.ok, c.row)
			continue
		}
		if !ok {
			continue
		}
		want := rows[c.row]
		want.Args = c.args
		if !reflect.DeepEqual(m, want) {
			t.Errorf("case %d (%s %+v): move %+v, want %+v", k, c.state, c.in, m, want)
		}
	}
}

func TestStates(t *testing.T) {
	if Terminal(StateAdmit) != false {
		t.Errorf("Terminal(%q)", StateAdmit)
	}
	if Terminal(StateSearch) != false {
		t.Errorf("Terminal(%q)", StateSearch)
	}
	if Terminal(StateFirstWrite) != false {
		t.Errorf("Terminal(%q)", StateFirstWrite)
	}
	if Terminal(StateCleanup) != false {
		t.Errorf("Terminal(%q)", StateCleanup)
	}
	if Terminal(StateLive) != true {
		t.Errorf("Terminal(%q)", StateLive)
	}
	if Terminal(StateRejected) != true {
		t.Errorf("Terminal(%q)", StateRejected)
	}
	if Initial != StateAdmit {
		t.Errorf("Initial %q", Initial)
	}
	if _, _, err := Step("no-such-state", In{}); err == nil {
		t.Error("Step on an unknown state")
	}
}

type record struct {
	calls []string
	args  [][]any
}

func (r *record) Noop() error {
	r.calls = append(r.calls, "noop")
	r.args = append(r.args, []any{})
	return nil
}

func (r *record) Reject(a0 string) error {
	r.calls = append(r.calls, "reject")
	r.args = append(r.args, []any{a0})
	return nil
}

func (r *record) Write(a0 string, a1 map[string]any) error {
	r.calls = append(r.calls, "write")
	r.args = append(r.args, []any{a0, a1})
	return nil
}

func (r *record) Wait() error {
	r.calls = append(r.calls, "wait")
	r.args = append(r.args, []any{})
	return nil
}

func (r *record) Live() error {
	r.calls = append(r.calls, "live")
	r.args = append(r.args, []any{})
	return nil
}

func (r *record) FirstWriteToCleanup(in In) error {
	r.calls = append(r.calls, "-FirstWriteToCleanup")
	r.args = append(r.args, []any{})
	return nil
}

// TestApply — Apply calls exactly the action of each row once (a YOURS procedure by its method).
func TestApply(t *testing.T) {
	for _, c := range formCases {
		m, ok, err := Step(c.state, c.in)
		if !ok || err != nil {
			continue
		}
		r := &record{}
		if err := Apply(r, c.in, m); err != nil {
			t.Fatalf("row %d: Apply: %v", m.Row, err)
		}
		want := m.Action
		if want == "" {
			want = "-" + m.Proc
		}
		if len(r.calls) != 1 || r.calls[0] != want || (m.Action != "" && !reflect.DeepEqual(r.args[0], m.Args)) {
			t.Fatalf("row %d: calls %v %v, want %s %v", m.Row, r.calls, r.args, want, m.Args)
		}
	}
	if err := Apply(&record{}, In{}, Move{Row: 99}); err == nil {
		t.Error("Apply of an empty move")
	}
}
